function ScreenToWorldAtZ(screenX, screenY, z) {
    if (!GameUI.GetScreenWorldPosition || !Game.WorldToScreenX || !Game.WorldToScreenY) {
        return null;
    }
    var base = GameUI.GetScreenWorldPosition(screenX, screenY);
    if (!base) {
        return null;
    }
    var guess = [base[0], base[1], z];
    var step = 64;
    for (var i = 0; i < 5; i++) {
        var sx = Game.WorldToScreenX(guess[0], guess[1], guess[2]);
        var sy = Game.WorldToScreenY(guess[0], guess[1], guess[2]);
        if (!isFinite(sx) || !isFinite(sy)) {
            break;
        }
        var dx = screenX - sx;
        var dy = screenY - sy;
        if (Math.abs(dx) + Math.abs(dy) < 1) {
            break;
        }
        var sx_dx = Game.WorldToScreenX(guess[0] + step, guess[1], guess[2]);
        var sy_dx = Game.WorldToScreenY(guess[0] + step, guess[1], guess[2]);
        var sx_dy = Game.WorldToScreenX(guess[0], guess[1] + step, guess[2]);
        var sy_dy = Game.WorldToScreenY(guess[0], guess[1] + step, guess[2]);
        var a = (sx_dx - sx) / step;
        var b = (sx_dy - sx) / step;
        var c = (sy_dx - sy) / step;
        var d = (sy_dy - sy) / step;
        var det = a * d - b * c;
        if (!isFinite(det) || Math.abs(det) < 1e-6) {
            break;
        }
        var invA = d / det;
        var invB = -b / det;
        var invC = -c / det;
        var invD = a / det;
        var deltaX = invA * dx + invB * dy;
        var deltaY = invC * dx + invD * dy;
        guess[0] += deltaX;
        guess[1] += deltaY;
    }
    return guess;
}

