     if (GameEvents) {
         var payload = {};
+        var targetZ = null;
+        if (shop1DragFx.sourceEnt && shop1DragFx.sourceEnt > 0 && Entities && Entities.GetAbsOrigin) {
+            var srcPos = Entities.GetAbsOrigin(shop1DragFx.sourceEnt);
+            if (srcPos && srcPos.length >= 3 && isFinite(srcPos[2])) {
+                targetZ = srcPos[2];
+            }
+        }
         var cursorPos = GameUI.GetCursorPosition();
         if (cursorPos && cursorPos.length >= 2) {
-            var world = ScreenToWorldAtZ(cursorPos[0], cursorPos[1], z_height);
-            if (!world && GameUI.GetScreenWorldPosition) {
-                world = GameUI.GetScreenWorldPosition(cursorPos[0], cursorPos[1]);
-            }
+            var world = null;
+            if (targetZ !== null) {
+                world = ScreenToWorldAtZ(cursorPos[0], cursorPos[1], targetZ);
+            }
+            if (!world && GameUI.GetScreenWorldPosition) {
+                world = GameUI.GetScreenWorldPosition(cursorPos[0], cursorPos[1]);
+                if (world && targetZ !== null) {
+                    world[2] = targetZ;
+                }
+            }
             if (world) {
                 payload.x = world[0];
                 payload.y = world[1];
                 payload.z = world[2];
             }
         }
